package org.example.model;

import java.util.List;
import java.util.Objects;

public class Teacher {
    private String name;
    private String subject;
    private int maxHours;
    private List<String> classes;

    public Teacher(String name, String subject, int maxHours, List<String> classes) {
        this.name = name;
        this.subject = subject;
        this.maxHours = maxHours;
        this.classes = classes;
    }

    public String getName() {
        return name;
    }

    public String getSubject() {
        return subject;
    }

    public int getMaxHours() {
        return maxHours;
    }

    public List<String> getClasses() {
        return classes;
    }

    @Override
    public String toString() {
        return "Teacher{" +
                "name='" + name + '\'' +
                ", subject='" + subject + '\'' +
                ", maxHours=" + maxHours +
                ", classes=" + classes +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Teacher)) return false;
        Teacher teacher = (Teacher) o;
        return maxHours == teacher.maxHours &&
                Objects.equals(name, teacher.name) &&
                Objects.equals(subject, teacher.subject) &&
                Objects.equals(classes, teacher.classes);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, subject, maxHours, classes);
    }
}

package org.example.util;

import org.apache.poi.ss.usermodel.*;
import org.example.model.Teacher;

import java.io.FileInputStream;
import java.io.InputStream;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ExcelReader {
    /**
     * Read teachers from an Excel file. Assumptions/resilience:
     * - Reads the first sheet.
     * - Detects header columns by matching common Indonesian/English header names (e.g. "Nama", "Name", "Guru" for name;
     *   "Mata Pelajaran", "Subject", "Mapel" for subject; "Max", "Maks Jam", "Jam" for max hours; "Kelas", "Class" for classes).
     * - If classes are provided as a single cell (comma/semicolon/newline-separated), it will split them; if classes are laid out
     *   across multiple columns named like "Kelas 1", "Kelas 2" it will collect non-empty ones.
     */
    public static List<Teacher> readTeachers(String path) throws Exception {
        List<Teacher> teachers = new ArrayList<>();

        try (InputStream is = new FileInputStream(path); Workbook wb = WorkbookFactory.create(is)) {
            Sheet sheet = wb.getSheetAt(0);
            if (sheet == null) return teachers;

            Iterator<Row> rowIt = sheet.rowIterator();
            if (!rowIt.hasNext()) return teachers;

            Row header = rowIt.next();
            Map<String, Integer> headerMap = new HashMap<>();
            for (Cell c : header) {
                String hv = cellToString(c).toLowerCase(Locale.ROOT).trim();
                if (!hv.isEmpty()) headerMap.put(hv, c.getColumnIndex());
            }

            Integer idxName = findColumn(headerMap, Arrays.asList("nama", "name", "guru"));
            Integer idxSubject = findColumn(headerMap, Arrays.asList("mata pelajaran", "mata_pelajaran", "mapel", "subject", "pelajaran"));
            Integer idxMax = findColumn(headerMap, Arrays.asList("max", "maks jam", "maks_jam", "jam", "max hours", "max_hours","maks"));
            Integer idxClasses = findColumn(headerMap, Arrays.asList("kelas", "class", "classes"));

            // also detect any columns that are labeled like "kelas 1", "kelas1", "class1" etc
            List<Integer> kelasColumns = new ArrayList<>();
            for (Map.Entry<String, Integer> e : headerMap.entrySet()) {
                String h = e.getKey();
                if (h.startsWith("kelas") || h.startsWith("kelas ") || h.startsWith("class") || h.startsWith("kelas_") || h.matches(".*kelas\\s*\\d+.*") || h.matches(".*class\\s*\\d+.*")) {
                    kelasColumns.add(e.getValue());
                }
            }
            if (idxClasses != null && !kelasColumns.contains(idxClasses)) {
                kelasColumns.add(idxClasses);
            }

            while (rowIt.hasNext()) {
                Row r = rowIt.next();
                String name = idxName != null ? cellToString(r.getCell(idxName)) : "";
                String subject = idxSubject != null ? cellToString(r.getCell(idxSubject)) : "";
                String maxRaw = idxMax != null ? cellToString(r.getCell(idxMax)) : "";
                int maxHours = parseMaxHours(maxRaw);

                // collect classes
                Set<String> classes = new LinkedHashSet<>();
                if (idxClasses != null) {
                    String clsCell = cellToString(r.getCell(idxClasses));
                    if (!clsCell.isEmpty()) {
                        classes.addAll(splitClasses(clsCell));
                    }
                }
                for (Integer ci : kelasColumns) {
                    // ci.equals(idxClasses) already returns false when idxClasses is null, so explicit null check is unnecessary
                    if (ci.equals(idxClasses)) continue;
                    String v = cellToString(r.getCell(ci));
                    if (!v.isEmpty()) classes.add(v);
                }

                // if no name and no subject, skip row
                if ((name == null || name.isBlank()) && (subject == null || subject.isBlank())) continue;

                String nameTrim = name == null ? "" : name.trim();
                String subjectTrim = subject == null ? "" : subject.trim();

                Teacher t = new Teacher(nameTrim, subjectTrim, maxHours, new ArrayList<>(classes));
                teachers.add(t);
            }
        }

        return teachers;
    }

    private static Integer findColumn(Map<String, Integer> headerMap, List<String> keywords) {
        for (String kw : keywords) {
            for (String h : headerMap.keySet()) {
                if (h.equalsIgnoreCase(kw) || h.contains(kw)) return headerMap.get(h);
            }
        }
        return null;
    }

    private static String cellToString(Cell c) {
        if (c == null) return "";
        try {
            switch (c.getCellType()) {
                case STRING:
                    return c.getStringCellValue();
                case NUMERIC:
                    if (DateUtil.isCellDateFormatted(c)) {
                        return c.getDateCellValue().toString();
                    } else {
                        double d = c.getNumericCellValue();
                        if (d == (long) d) return String.valueOf((long) d);
                        return String.valueOf(d);
                    }
                case BOOLEAN:
                    return String.valueOf(c.getBooleanCellValue());
                case FORMULA:
                    try {
                        return c.getStringCellValue();
                    } catch (Exception ex) {
                        try {
                            double d = c.getNumericCellValue();
                            if (d == (long) d) return String.valueOf((long) d);
                            return String.valueOf(d);
                        } catch (Exception ex2) {
                            return c.toString();
                        }
                    }
                case BLANK:
                default:
                    return "";
            }
        } catch (Exception e) {
            return c.toString();
        }
    }

    private static int parseMaxHours(String raw) {
        if (raw == null) return 0;
        String s = raw.trim();
        if (s.isEmpty()) return 0;
        // try numeric parse
        try {
            double d = Double.parseDouble(s.replaceAll("[^0-9.,]", ""));
            return (int) Math.round(d);
        } catch (Exception ignored) {
        }
        // find digits in string
        Pattern p = Pattern.compile("(\\d+)");
        Matcher m = p.matcher(s);
        if (m.find()) {
            try {
                return Integer.parseInt(m.group(1));
            } catch (Exception ignored) {
            }
        }
        return 0;
    }

    private static List<String> splitClasses(String cell) {
        List<String> out = new ArrayList<>();
        if (cell == null) return out;
        String[] parts = cell.split("[,;\\n\\r]+");
        for (String p : parts) {
            if (p == null) continue;
            String t = p.trim();
            if (!t.isEmpty()) out.add(t);
        }
        return out;
    }
}

package org.example.util;

import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.example.model.Teacher;

import java.io.FileOutputStream;
import java.io.OutputStream;
import java.util.List;
import java.util.stream.Collectors;

public class ExcelWriter {
    public static void writeTeachers(List<Teacher> teachers, String outPath) throws Exception {
        try (Workbook wb = new XSSFWorkbook()) {
            Sheet sheet = wb.createSheet("Teachers");

            // header
            Row header = sheet.createRow(0);
            header.createCell(0).setCellValue("Name");
            header.createCell(1).setCellValue("Subject");
            header.createCell(2).setCellValue("MaxHours");
            header.createCell(3).setCellValue("Classes");

            int r = 1;
            for (Teacher t : teachers) {
                Row row = sheet.createRow(r++);
                row.createCell(0).setCellValue(t.getName());
                row.createCell(1).setCellValue(t.getSubject());
                row.createCell(2).setCellValue(t.getMaxHours());
                String classes = t.getClasses() == null ? "" : t.getClasses().stream().collect(Collectors.joining(", "));
                row.createCell(3).setCellValue(classes);
            }

            for (int i = 0; i < 4; i++) sheet.autoSizeColumn(i);

            try (OutputStream os = new FileOutputStream(outPath)) {
                wb.write(os);
            }
        }
    }
}
